#!/usr/bin/env python3
"""
Round 173b (culprits), 4 October 2026. Needs round 172b.

ESDAC soil maps and WBA Nature Benchmark rows (the lost round 148b).

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 173b (4 October)\n\nNeeds round 172b (guards on its heading). Tiles patch round173b_tiles.py\nbeside it. No app.js?v= bump. Redoes the lost round 148b.\n\n- Soil biodiversity is led by the Global Soil Biodiversity Atlas's two maps:\n  esdac_soil_biodiversity (potential soil biodiversity, Atlas pp. 90-91) and\n  esdac_soil_threats (potential threats to soil organisms, pp. 134-135).\n  Built in the sandbox from the owner's GeoTIFFs (soil_bio_new.tif,\n  threat_soil_bio.tif; float, 0.1 degree) with scripts/lib/pyramid.py: five\n  steps, each a fifth of the map's own places, RAMP5, zoom 0-6, mean of the\n  steps under each pixel. Only coloured pictures and plain keys are published\n  (no values): ESDAC allowed display with its citation and forbids passing\n  the data on. The GeoTIFFs are in neither repo.\n- wba_nature_companies under Biodiversity loss > Companies and financiers:\n  the World Benchmarking Alliance's Nature Benchmark (CC BY 4.0), every\n  column, at the headquarters country's capital on a spiral. Tiles\n  scripts/wba_nature.py reads WBA's Data API (base URL and endpoints from\n  WBA's API specification page: /datasets/benchmarks, /datasets/companies,\n  their /cols; per_page 1000; one request a second; Bearer key). Columns are\n  found by name and recorded in wba/build.json and wba/columns.json; rows\n  whose benchmark name holds \"Nature\" are kept; countries matched exactly\n  (pycountry lookup, no fuzzy match). Without the WBA_API_KEY secret it says\n  so in wba/build.json and exits 0. Tested only against a stand-in API.\n- 147b's colour box per layer is still to be redone.\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round173b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 172b" not in h.read_text(encoding="utf-8"):
        sys.exit("round173b: round 172b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round173b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round173b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round173b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
